/* Blur-only pointer controls. Geometry is written to the same clip used by export/MCP. */
const blurBox=document.createElement('div');blurBox.id='blur-transform-box';blurBox.hidden=true;blurBox.tabIndex=0;blurBox.setAttribute('aria-label','Blur rectangle: drag to move, use handles to resize');
blurBox.innerHTML='<span class="blur-box-label">BLUR · Drag to move</span>'+['nw','n','ne','e','se','s','sw','w'].map(edge=>`<button data-blur-edge="${edge}" class="blur-handle ${edge}" aria-label="Resize blur ${edge}" title="Drag to resize blur"></button>`).join('');$('#stage').append(blurBox);
let blurGesture=null;
function selectedBlur(){const c=current();return c&&c.track==='blur'&&getSelectionIds().length===1&&isActive(c,Math.min(playhead,Math.max(0,duration()-.001)))&&!project.muted.blur?c:null;}
function refreshBlurBox(){const c=selectedBlur(),show=c&&!exporting&&!blurDrawing;blurBox.hidden=!show;if(!show)return;const r=canvasBounds(),stage=$('#stage').getBoundingClientRect(),pose=Model.poseAt(c,playhead-c.start);Object.assign(blurBox.style,{left:r.left-stage.left+r.width*(.5+pose.x/100-pose.width/200)+'px',top:r.top-stage.top+r.height*(.5+pose.y/100-pose.height/200)+'px',width:r.width*pose.width/100+'px',height:r.height*pose.height/100+'px'});blurBox.classList.toggle('locked',clipLocked(c));$$('button',blurBox).forEach(b=>b.disabled=clipLocked(c));$('#region-draft').hidden=true;}
const frameBeforeBlurBox=drawFrame;drawFrame=function(){frameBeforeBlurBox();refreshBlurBox();};
const inspectorBeforeBlurBox=renderInspector;renderInspector=function(){inspectorBeforeBlurBox();refreshBlurBox();};
function startBlurGesture(e,edge=null){const c=selectedBlur();if(e.button!==0||!c||exporting||blurDrawing||clipLocked(c))return;e.preventDefault();e.stopImmediatePropagation();stop();const pose=Model.poseAt(c,playhead-c.start),r=canvasBounds();blurGesture={id:c.id,edge,pointerId:e.pointerId,startX:e.clientX,startY:e.clientY,rect:{left:.5+pose.x/100-pose.width/200,top:.5+pose.y/100-pose.height/200,right:.5+pose.x/100+pose.width/200,bottom:.5+pose.y/100+pose.height/200},width:r.width,height:r.height,before:Model.clone(c),history:[...past],redo:[...future],changed:false,time:playhead};try{blurBox.setPointerCapture?.(e.pointerId);}catch{}}
blurBox.addEventListener('pointerdown',e=>startBlurGesture(e,e.target.closest('[data-blur-edge]')?.dataset.blurEdge||null));
canvas.addEventListener('pointerdown',e=>{if(e.button!==0||exporting||blurDrawing)return;const c=selectedBlur();if(!c)return;const p=pointOnCanvas(e),pose=Model.poseAt(c,playhead-c.start),inside=Math.abs(p.x-(.5+pose.x/100))<=pose.width/200&&Math.abs(p.y-(.5+pose.y/100))<=pose.height/200;if(inside)startBlurGesture(e);else e.stopImmediatePropagation();},true);
window.addEventListener('pointermove',e=>{const d=blurGesture;if(!d||e.pointerId!==d.pointerId)return;const c=project.clips.find(c=>c.id===d.id);if(!c||exporting||clipLocked(c)||playhead!==d.time)return finishBlurGesture(true);const dx=(e.clientX-d.startX)/d.width,dy=(e.clientY-d.startY)/d.height;if(!d.changed&&Math.hypot(e.clientX-d.startX,e.clientY-d.startY)<3)return;if(!d.changed){checkpoint();d.changed=true;}let {left:l,top:t,right:r,bottom:b}=d.rect;const minW=Math.min(1,Math.max(.01,8/d.width)),minH=Math.min(1,Math.max(.01,8/d.height));if(d.edge){if(d.edge.includes('w'))l=clamp(l+dx,0,r-minW);if(d.edge.includes('e'))r=clamp(r+dx,l+minW,1);if(d.edge.includes('n'))t=clamp(t+dy,0,b-minH);if(d.edge.includes('s'))b=clamp(b+dy,t+minH,1);}else{const width=r-l,height=b-t;l=clamp(l+dx,0,1-width);t=clamp(t+dy,0,1-height);r=l+width;b=t+height;}Object.assign(c,{x:((l+r)/2-.5)*100,y:((t+b)/2-.5)*100,width:(r-l)*100,height:(b-t)*100});if(c.keyframes.length)upsertKeyframe(c,{x:c.x,y:c.y,width:c.width,height:c.height});drawFrame();e.preventDefault();});
function finishBlurGesture(cancel=false){const d=blurGesture;if(!d)return;blurGesture=null;try{if(blurBox.hasPointerCapture?.(d.pointerId))blurBox.releasePointerCapture(d.pointerId);}catch{}if(d.changed){if(cancel){const c=project.clips.find(c=>c.id===d.id);if(c)Object.assign(c,d.before);past=d.history;future=d.redo;renderAll();drawFrame();}else{renderInspector();scheduleSave();}}refreshBlurBox();}
window.addEventListener('pointerup',e=>{if(blurGesture&&e.pointerId===blurGesture.pointerId)finishBlurGesture();});window.addEventListener('pointercancel',()=>finishBlurGesture(true));window.addEventListener('blur',()=>finishBlurGesture());window.addEventListener('keydown',e=>{if(e.key==='Escape'&&blurGesture){e.preventDefault();finishBlurGesture(true);}});
